export interface ConnectorConfig {
  /** Slack bot token with chat:write scope. */
  slackBotToken: string
  /** Slack channel ID (e.g., C1234567890) or channel name. */
  slackChannel: string
  /** Optional fetch implementation for testing or custom environments. */
  fetch?: typeof fetch
}

export interface CalendlyInviteePayload {
  event: string
  created_at: string
  created_by: string
  payload: {
    uri: string
    email: string
    name: string
    status: string
    timezone: string
    event: string
    created_at: string
    updated_at: string
    cancel_url: string
    reschedule_url: string
    questions_and_answers: Array<{
      question: string
      answer: string
      position: number
    }>
    tracking?: Record<string, string>
  }
}

export interface HandleResult {
  /** Slack message timestamp (ts) returned from chat.postMessage. */
  slackMessageTs: string
  /** Slack channel ID where the message was posted. */
  slackChannel: string
}

function validatePayload(payload: unknown): asserts payload is CalendlyInviteePayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object')
  }
  const p = payload as Record<string, unknown>
  if (p.event !== 'invitee.created') {
    throw new Error(`Unsupported event type: ${p.event}`)
  }
  const inner = p.payload as Record<string, unknown> | undefined
  if (!inner) throw new Error('Missing payload.payload')
  if (!inner.name || typeof inner.name !== 'string') {
    throw new Error('Missing required field: payload.name')
  }
  if (!inner.email || typeof inner.email !== 'string') {
    throw new Error('Missing required field: payload.email')
  }
  if (!Array.isArray(inner.questions_and_answers)) {
    throw new Error('Missing required field: payload.questions_and_answers (array)')
  }
}

function formatMessage(payload: CalendlyInviteePayload): string {
  const { name, email, questions_and_answers } = payload.payload
  const answersText = questions_and_answers
    .sort((a, b) => a.position - b.position)
    .map((qa) => `${qa.question} ${qa.answer}`)
    .join('; ')
  return `${name} (${email}) booked a meeting. Answers: ${answersText}`
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const calendlyPayload = payload as CalendlyInviteePayload
  const text = formatMessage(calendlyPayload)

  const fetchImpl = config.fetch ?? fetch
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({
    channel: config.slackChannel,
    text,
  })

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const data = await response.json() as { ok: boolean; channel: string; ts: string; message?: unknown }
  if (!data.ok) {
    throw new Error(`Slack API returned ok=false for POST ${url}`)
  }

  return {
    slackMessageTs: data.ts,
    slackChannel: data.channel,
  }
}

